"""context_extractor: PDF text extraction and keyword building for Soniox context.

Provides extract_text_from_pdf, extract_keywords_from_text (LLM or frequency
fallback), and build_soniox_context which combines multiple docs into a
Soniox-compatible context dict.
"""
from __future__ import annotations

import json
import re
from collections import Counter
from typing import Any

from atcli.utils.logger import get_logger

logger = get_logger(__name__)


def extract_text_from_pdf(path: str) -> str:
    """Extract all text from a PDF file using pypdf."""
    try:
        from pypdf import PdfReader  # type: ignore[import]
    except ImportError as exc:
        raise RuntimeError("pypdf is required: pip install pypdf") from exc

    reader = PdfReader(path)
    pages = [page.extract_text() or "" for page in reader.pages]
    return "\n".join(pages)


def _normalize_pdf_text(text: str) -> str:
    """Normalize PDF text: collapse char-spaced words, remove excess whitespace."""
    # Collapse char-spaced runs: 'L i v e' → 'Live'
    text = re.sub(r"\b[A-Za-z](?: [A-Za-z])+\b", lambda m: m.group(0).replace(" ", ""), text)
    # Replace newlines and tabs with single space
    text = re.sub(r"[\n\r\t]+", " ", text)
    # Collapse multiple spaces
    text = re.sub(r" {2,}", " ", text)
    return text.strip()


def _simple_keyword_extract(text: str, max_kw: int = 30) -> list[str]:
    """Frequency-based keyword fallback — no LLM required."""
    text = _normalize_pdf_text(text)
    stopwords = {
        "the", "and", "of", "to", "a", "in", "is", "for", "on", "that",
        "with", "as", "by", "an", "are", "be", "this", "or", "at", "it",
        "from", "was", "we", "our", "their", "which", "have", "has",
    }
    # Match single words (≥3 chars) or 2-word phrases, letters only (Latin + Vietnamese)
    words = re.findall(r"[A-Za-zÀ-ÿĀ-ɏḀ-ỿ]{3,}(?:[ ][A-Za-zÀ-ÿĀ-ɏḀ-ỿ]{2,})?", text.lower())
    filtered = [w for w in words if not any(tok in stopwords for tok in w.split())]
    counts = Counter(filtered)
    return [w.strip() for w, _ in counts.most_common(max_kw)]


def _llm_keyword_extract(
    text: str,
    max_kw: int,
    api_key: str,
    endpoint: str,
) -> list[str]:
    """Call an OpenAI-compatible API to extract keywords from text."""
    import httpx  # already in project deps

    prompt = (
        "Extract the most important keywords and short keyphrases from the following text. "
        f'Return a JSON object with a single key "keywords" whose value is an array of strings. '
        f"Include up to {max_kw} items. No duplicates, no explanations.\n\nText:\n{text[:15000]}"
    )
    payload = {
        "model": "gpt-4o-mini",
        "messages": [{"role": "user", "content": prompt}],
    }
    headers = {"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"}

    try:
        resp = httpx.post(f"{endpoint.rstrip('/')}/chat/completions", json=payload, headers=headers, timeout=60.0)
        resp.raise_for_status()
        content = resp.json()["choices"][0]["message"]["content"]

        # Try direct parse, then extract JSON substring
        try:
            parsed = json.loads(content)
        except json.JSONDecodeError:
            m = re.search(r"\{.*\}", content, re.S)
            parsed = json.loads(m.group(0)) if m else {}

        kws = parsed.get("keywords", [])
        return [k.strip() for k in kws if isinstance(k, str) and k.strip()]
    except Exception as exc:
        logger.warning("LLM keyword extraction failed (%s), using frequency fallback.", exc)
        return []


def extract_keywords_from_text(
    text: str,
    max_kw: int = 30,
    llm_api_key: str | None = None,
    llm_endpoint: str | None = None,
) -> list[str]:
    """Extract keywords from text, using LLM if credentials provided, else frequency approach."""
    if not text or not text.strip():
        return []

    keywords: list[str] = []
    if llm_api_key and llm_endpoint:
        keywords = _llm_keyword_extract(text, max_kw, llm_api_key, llm_endpoint)

    if not keywords:
        keywords = _simple_keyword_extract(text, max_kw)

    # Deduplicate while preserving order
    seen: set[str] = set()
    result: list[str] = []
    for kw in keywords:
        if kw not in seen:
            seen.add(kw)
            result.append(kw)
    return result[:max_kw]


def build_soniox_context(
    doc_paths: list[str],
    hints: str = "",
    llm_api_key: str | None = None,
    llm_endpoint: str | None = None,
) -> dict[str, Any]:
    """Build a Soniox context dict from reference PDF documents and optional free-text hints.

    Args:
        doc_paths:    Paths to PDF reference documents.
        hints:        Free-text string passed as context["text"] (e.g. topic description).
        llm_api_key:  Optional OpenAI-compatible API key for keyword extraction.
        llm_endpoint: Optional API endpoint URL.

    Returns:
        dict with keys "text" and "terms" suitable for Soniox transcription config.
    """
    if not doc_paths:
        return {"text": hints, "terms": []}

    all_text_parts: list[str] = []
    for path in doc_paths:
        try:
            logger.info("Extracting text from %s...", path)
            text = extract_text_from_pdf(path)
            all_text_parts.append(text)
        except Exception as exc:
            logger.warning("Skipping %s: %s", path, exc)

    combined_text = "\n\n".join(all_text_parts)
    keywords = extract_keywords_from_text(combined_text, llm_api_key=llm_api_key, llm_endpoint=llm_endpoint)
    logger.info("Extracted %d keywords from %d document(s).", len(keywords), len(doc_paths))

    return {"text": hints, "terms": keywords}
